import { TL } from '../data/tabsLive.js'

function sameList(a, b) {
  if (!Array.isArray(a) || !Array.isArray(b) || a.length !== b.length) return false
  return a.every((v, i) => String(v) === String(b[i]))
}

function parseHTML(html) {
  if (typeof document === 'undefined') return null
  const tpl = document.createElement('template')
  tpl.innerHTML = html
  return tpl.content
}

function itemsOf(container, rtype) {
  const kids = Array.from(container.children || [])
  if (rtype === 'config-list') return kids.filter((k) => k.tagName.toLowerCase() === 'a')
  if (rtype === 'icon-toggle') return kids.filter((k) => k.tagName.toLowerCase() === 'span' && /icon-/.test(k.className || ''))
  if (rtype === 'pill-switch' || rtype === 'pill-anim' || rtype === 'pill' || rtype === 'trans-parent')
    return kids.filter((k) => k.tagName.toLowerCase() === 'button')
  return kids.filter((k) => {
    const cls = k.className || ''
    if (k.tagName.toLowerCase() === 'div' && /absolute/.test(cls) && /transition/.test(cls) && /bg-/.test(cls)) return false
    return ['a', 'button', 'div', 'span', 'li'].includes(k.tagName.toLowerCase())
  })
}

function setLabel(el, text) {
  const label = String(text)
  const p = el.querySelector('p')
  if (p && !p.querySelector('[class*="icon-"]')) { p.textContent = label; return }
  for (const node of Array.from(el.childNodes)) {
    if (node.nodeType === 3 && node.textContent.trim()) { node.textContent = label; return }
  }
  const span = Array.from(el.children).find((c) => c.tagName.toLowerCase() === 'span' && !/icon-|rounded|border|badge/.test(c.className || '') && !c.children.length)
  if (span) { span.textContent = label; return }
  if (!el.children.length) { el.textContent = label; return }
  // Keep badge children: replace only the first text-bearing leaf
  for (const leaf of el.querySelectorAll('span,p')) { if (!leaf.children.length && leaf.textContent.trim() && !/^\d+$/.test(leaf.textContent.trim())) { leaf.textContent = label; return } }
}

function setCount(el, n) {
  const badge = Array.from(el.querySelectorAll('span,div')).find((x) => /rounded-2xl|badge/.test(x.className || '') && /^\d+$/.test(x.textContent.trim().replace(/[()]/g, '')))
  if (badge) { badge.textContent = String(n); return }
}

export function Tabs({ group = 1, state = 'default', activeIndex, tabs, counts, showCountBadges, disabledIndices }) {
  const g = TL[`group${group}`] || TL.group1
  const cells = g.cells || {}
  const st = cells[state] ? state : (cells.default ? 'default' : Object.keys(cells)[0])
  const cell = cells[st]
  if (!cell || !cell.outer) return null
  const capAct = cell.activeIndex ?? 0
  const capLabels = cell.labels || []
  const capCounts = cell.counts || null

  // If the props already equal what was captured, render the captured markup verbatim (no re-serialisation).
  const actSame = activeIndex == null || activeIndex === capAct
  const labelsSame = !tabs || !tabs.length || sameList(tabs, capLabels)
  const countsSame = !counts || !counts.length || (capCounts && sameList(counts, capCounts))
  if (actSame && labelsSame && countsSame) {
    return <div style={{ display: 'contents' }} dangerouslySetInnerHTML={{ __html: cell.outer }} />
  }

  const frag = parseHTML(cell.outer)
  const container = frag && frag.firstElementChild
  if (!container) return <div style={{ display: 'contents' }} dangerouslySetInnerHTML={{ __html: cell.outer }} />
  const items = itemsOf(container, cell.rtype)
  const useIdx = activeIndex != null ? activeIndex : capAct
  items.forEach((el, i) => {
    const cls = i === useIdx ? (g.activeClass || el.getAttribute('class')) : (g.inactiveClass || el.getAttribute('class'))
    if (cls) el.setAttribute('class', cls)
    const tag = el.tagName.toLowerCase()
    if (tag === 'a') { if (i === useIdx) el.setAttribute('aria-current', 'page'); else el.removeAttribute('aria-current') }
    else if (tag === 'button' || el.getAttribute('role') === 'tab') el.setAttribute('aria-selected', i === useIdx ? 'true' : 'false')
    if (tag === 'button' && disabledIndices && disabledIndices.includes(i)) { el.setAttribute('disabled', 'true'); el.setAttribute('aria-disabled', 'true') }
    if (tabs && tabs[i] != null && !sameList([tabs[i]], [capLabels[i]])) setLabel(el, tabs[i])
    if (counts && counts[i] != null && (!capCounts || String(counts[i]) !== String(capCounts[i]))) setCount(el, counts[i])
  })
  return <div style={{ display: 'contents' }} dangerouslySetInnerHTML={{ __html: container.outerHTML }} />
}

export const LIVE_TAB_GROUPS = Object.keys(TL).filter((k) => k.startsWith('group')).map((k) => parseInt(k.replace('group', ''), 10))
